// Format recent filings with human-readable USD billions/millions for Slack/Email digests
const fmtUsd = (n) => {
  if (typeof n !== 'number') return 'N/A';
  if (Math.abs(n) >= 1e9) return '$' + (n / 1e9).toFixed(2) + 'B';
  if (Math.abs(n) >= 1e6) return '$' + (n / 1e6).toFixed(1) + 'M';
  return '$' + n.toLocaleString();
};

return $input.all().map(item => {
  const f = item.json;
  const fin = f.xbrlFinancialSnapshot || {};
  return {
    json: {
      ticker: f.ticker,
      company: f.companyName,
      form: f.form,
      filingDate: f.filingDate,
      filingUrl: f.filingUrl,
      latestRevenue: fmtUsd(fin.revenueUsd),
      latestNetIncome: fmtUsd(fin.netIncomeUsd),
      latestCash: fmtUsd(fin.cashUsd),
      alertHeadline: `[${f.ticker}] New SEC Form ${f.form} (${f.filingDate}) — Rev: ${fmtUsd(fin.revenueUsd)}, Cash: ${fmtUsd(fin.cashUsd)}`
    }
  };
});
